#ifndef __MEM_INIT_H__
#define __MEM_INIT_H__

#include "../scamptrie_base.h"
#include "../image.hpp"
#include "../fib.hpp"

class ScampTrieDynamic;

// Typed memory exporter.
//
// capture() turns the live FIB into the compact, self contained image of
// PROTOCOL.md: eleven stages of half/full node cells, the NI pattern
// dictionary, the NI value vector and the explicit front locators.  The live
// trie is walked to keep the two representations in step; the authoritative
// prefix set is the exact model kept next to it.
class MemInit {
public:
    MemInit(const ScampTrieDynamic* trie, const Fib& fib);
    ~MemInit();

    ImageData capture();

private:
    const ScampTrieDynamic* trie_;
    const Fib* fib_;
    ImageData image_;
};

#endif // __MEM_INIT_H__
EOF
cat > /workspace/src/utils/mem_init.cpp <<'EOF'
#include "../scamptrie_dynamic.h"
#include "mem_init.h"

MemInit::MemInit(const ScampTrieDynamic* trie, const Fib& fib) : trie_(trie), fib_(&fib) {}
MemInit::~MemInit() {}

ImageData MemInit::capture() {
    image_ = build_image(*fib_);
    return image_;
}
EOF
